CREATE OR REPLACE FUNCTION public.publish_monitor_refresh_claim(p_limit integer, p_lease_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE now_at timestamptz:=clock_timestamp(); today date:=(clock_timestamp() AT TIME ZONE 'UTC')::date;
